def shade(cell, fill):
    tcPr=cell._tc.get_or_add_tcPr(); shd=OxmlElement('w:shd'); shd.set(qn('w:fill'),fill); tcPr.append(shd)
def set_cell(cell, text, bold=False, color=None, size=9):
    cell.text=''; p=cell.paragraphs[0]; p.paragraph_format.space_after=Pt(2)
    r=p.add_run(text); r.bold=bold; r.font.name='Aptos'; r.font.size=Pt(size)
    if color: r.font.color.rgb=RGBColor(*color)
    cell.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
def table(rows, widths=None):
    t=doc.add_table(rows=0, cols=len(rows[0])); t.alignment=WD_TABLE_ALIGNMENT.CENTER
    t.style='Table Grid'
    for ri,row in enumerate(rows):
        cells=t.add_row().cells
        for ci,value in enumerate(row):
            set_cell(cells[ci], str(value), bold=(ri==0), color=((255,255,255) if ri==0 else None))
            if ri==0: shade(cells[ci], '24476B')
            elif ri%2==0: shade(cells[ci], 'F1F5F8')
            if widths: cells[ci].width=Inches(widths[ci])
    doc.add_paragraph().paragraph_format.space_after=Pt(2)
    return t

def para(text, boldlead=None):
    p=doc.add_paragraph()
    if boldlead and text.startswith(boldlead):
        p.add_run(boldlead).bold=True; p.add_run(text[len(boldlead):])
    else: p.add_run(text)
    return p

def page(title, paragraphs, matrix=None, heading=''):
    if len(doc.paragraphs) or len(doc.tables): doc.add_page_break()
    if heading:
        p=doc.add_paragraph(heading.upper()); p.paragraph_format.space_after=Pt(4)
        for r in p.runs: r.font.size=Pt(8); r.font.bold=True; r.font.color.rgb=RGBColor(55,105,145)
    doc.add_heading(title, 1)
    for x in paragraphs: para(x)
    if matrix: table(matrix)

